  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 How the Internet Works$j$, $j${"readings": [{"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}], "body": "The internet is a worldwide network of networks that connects billions of devices. Psalm 19:4 says of God's creation, Their line is gone out through all the earth, and their words to the end of the world. The internet now carries words, sounds and pictures to the ends of the earth, and it can be used to spread the gospel as well as to spread harm.\n\nThe internet is not the same thing as the World Wide Web. The internet is the infrastructure, made of cables, towers, satellites, routers and servers. The web is a service that runs on the internet. It is a system of pages and files you view with a browser. Email, video calls and online games also use the internet.\n\nHere is how it works. A client is a device that asks for information, such as your phone or laptop. A server is a computer that stores information and sends it when asked. Your internet service provider, or ISP, connects you to the wider internet. Every device has an IP address, a number that identifies it so data knows where to go. Because numbers are hard to remember, the Domain Name System, or DNS, works like a phone book, turning a name like newlifeprep.org into the number of the right server.\n\nA web address is called a URL. It includes the protocol, the domain name and the path to a page. The protocol HTTP is the set of rules for sending web pages. HTTPS adds encryption, which scrambles data so others cannot read it, and the lock symbol in the browser shows a secure connection. Look for HTTPS before entering passwords or payment information.\n\nData does not travel in one piece. It is broken into small packets, sent along different routes and put back together at the destination. Routers decide the path for each packet. This design lets the internet keep working even if part of it fails.\n\nYour task: (1) Explain the difference between the internet and the web. (2) Explain what DNS does. (3) Explain why HTTPS matters.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Psalm 19:4 says, Their line is gone out through all the earth, and their words to the end of the world. The internet now carries words to the ends of the earth, and we can use it to spread the gospel.\n\nNow watch this. The internet is a worldwide network of networks. It is the infrastructure of cables, towers, satellites, routers and servers. The web is a service that runs on it, a system of pages you view with a browser. Email and video calls use the internet too.\n\nA client asks for information. A server stores it and sends it. Your ISP connects you to the internet. Every device has an IP address. DNS works like a phone book, turning a name like newlifeprep.org into the number of the right server.\n\nA URL is a web address. HTTP is the set of rules for web pages. HTTPS adds encryption. Look for the lock before entering passwords or payments.\n\nData is broken into packets, sent along different routes and put back together. Routers choose the path.\n\nYour task is to explain the internet and the web, DNS and HTTPS. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 How the Internet Works$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Networks, WiFi and Devices$j$, $j${"readings": [{"title": "Ecclesiastes 4 (King James Version)", "url": "/portal/bible/Ecclesiastes/4"}], "body": "A network is a group of connected devices that share information and resources. Ecclesiastes 4:12 says, a threefold cord is not quickly broken. Connected people and connected devices can do more together than apart.\n\nNetworks are described by size. A local area network, or LAN, covers a small area such as a home, a school or a church building. A wide area network, or WAN, covers a large area, and the internet is the largest WAN. A personal area network, such as Bluetooth between a phone and earbuds, covers a very short range.\n\nKnow the equipment. A modem connects your network to your internet service provider. A router directs traffic between devices and the internet, and often includes WiFi. A switch connects wired devices in a local network. An access point extends WiFi coverage. A network interface card lets a device connect. Ethernet is the wired connection, usually faster and more stable. WiFi is the wireless connection, which is convenient but shared and easier to intercept.\n\nBandwidth is how much data can be sent at once, often measured in megabits per second. More devices using a connection means less for each. A weak signal, distance and walls can slow WiFi.\n\nThe Internet of Things, or IoT, is the growing group of everyday objects connected to the internet, such as cameras, doorbells, speakers, thermostats and watches. They are convenient but can be a security risk if left with default passwords or out of date software.\n\nSecure your network. Change the default router name and password. Use the strongest encryption available, such as WPA3 or WPA2. Keep the router firmware updated. Create a guest network for visitors. Turn off features you do not use. On public WiFi, avoid sensitive tasks, or use a trusted virtual private network, or VPN, which encrypts your traffic. Confirm the network name with the owner, since criminals create fake hotspots with believable names.\n\nYour task: (1) Compare a LAN and a WAN. (2) Name the jobs of a modem and a router. (3) List four ways to secure a home network.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Ecclesiastes 4:12 says, a threefold cord is not quickly broken. Connected people and connected devices can do more together.\n\nNow watch this. A network is a group of connected devices that share information. A LAN covers a small area like a home, school or church. A WAN covers a large area, and the internet is the largest one. Bluetooth is a personal area network.\n\nA modem connects your network to your ISP. A router directs traffic and often provides WiFi. A switch connects wired devices. Ethernet is wired and usually faster and steadier. WiFi is wireless and convenient, but easier to intercept.\n\nBandwidth is how much data can be sent at once. More devices mean less for each.\n\nThe Internet of Things includes cameras, doorbells, speakers and watches. Change their default passwords and keep them updated.\n\nSecure your network. Change the router name and password. Use WPA3 or WPA2. Update the router. Use a guest network. On public WiFi, avoid sensitive tasks or use a trusted VPN. Confirm the network name, since fake hotspots exist.\n\nYour task is to compare LAN and WAN, name the jobs of a modem and router and list ways to secure a home network. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Networks, WiFi and Devices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Cybersecurity: Threats and Defenses$j$, $j${"readings": [{"title": "Nehemiah 4 (King James Version)", "url": "/portal/bible/Nehemiah/4"}], "body": "Cybersecurity is the practice of protecting devices, networks and information from attack. Nehemiah 4:9 says, Nevertheless we made our prayer unto our God, and set a watch against them day and night. Nehemiah prayed and posted guards while rebuilding the wall. We also pray and stay watchful. Churches, schools and families are targets, and Proverbs 22:3 reminds us that a prudent man foreseeth the evil.\n\nKnow the threats. Malware is harmful software. A virus attaches to files and spreads when they are opened. A worm spreads by itself across networks. A trojan pretends to be useful software. Spyware secretly watches your activity. Ransomware locks your files and demands payment. Adware shows unwanted advertisements.\n\nSocial engineering tricks people instead of machines. Phishing uses fake emails, texts or websites to steal passwords or money. Look for urgent threats, unknown senders, spelling errors, mismatched links and requests for passwords or gift cards. Do not click, and report it. Scams also include fake prizes, fake tech support and messages from a friend whose account was hacked. Attackers often impersonate a pastor or leader to request money, so confirm by another method.\n\nBuild layers of defense. Install updates, since they fix known weaknesses. Use antivirus software and a firewall, which filters traffic coming into and out of a network. Use strong, unique passwords with multifactor authentication. Download software only from official stores and trusted sites. Do not plug in unknown USB drives. Encrypt sensitive files and devices, and lock your screen. Limit who has administrator access, giving people only the access they need. Back up your files regularly, and keep a copy offline, so ransomware cannot destroy every copy.\n\nIf something goes wrong, act quickly. Disconnect from the network, tell a trusted adult or the person in charge of technology, change passwords from a clean device, run a scan and report fraud to the right authorities. Do not pay a ransom without expert advice. Learn from what happened and improve your defenses.\n\nYour task: (1) Define malware, ransomware and phishing. (2) List five layers of defense. (3) Describe what to do if you think your device has been hacked.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Nehemiah 4:9 says, Nevertheless we made our prayer unto our God, and set a watch against them day and night. Nehemiah prayed and posted guards. We pray and stay watchful.\n\nNow watch this. Cybersecurity protects devices, networks and information from attack. Malware is harmful software. A virus attaches to files. A worm spreads by itself. A trojan pretends to be useful. Spyware watches you. Ransomware locks your files and demands payment.\n\nSocial engineering tricks people. Phishing uses fake emails, texts or websites. Look for urgent threats, unknown senders, spelling errors, mismatched links and requests for passwords or gift cards. Attackers often pretend to be a pastor or leader asking for money. Confirm by another method.\n\nBuild layers. Install updates. Use antivirus and a firewall. Use strong passwords with multifactor authentication. Download from official stores. Do not plug in unknown USB drives. Encrypt sensitive files. Limit administrator access. Keep backups, including one offline copy.\n\nIf something goes wrong, disconnect, tell a trusted adult, change passwords from a clean device, scan and report fraud.\n\nYour task is to define malware, ransomware and phishing, list defenses and describe what to do after a hack. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Cybersecurity: Threats and Defenses$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Research, Evaluating Sources and Responsible Use of AI Tools$j$, $j${"readings": [{"title": "1 Thessalonians 5 (King James Version)", "url": "/portal/bible/1Thessalonians/5"}], "body": "Everyone can publish online, so not everything found there is true. 1 Thessalonians 5:21 says, Prove all things; hold fast that which is good. Good researchers test what they read before they trust or share it.\n\nSearch with skill. Choose specific keywords instead of whole questions. Put exact phrases in quotation marks. Narrow results by site type or date. Try different words if the first search fails. Remember that the first result is not always the best, and some top results are paid advertisements. Use library databases, government sites and academic sources for school research.\n\nEvaluate each source with five questions. Who is the author or publisher, and are they qualified? Is the information accurate, supported by evidence and confirmed by other reliable sources? What is the purpose, whether to inform, teach, sell, persuade or entertain? Is it current enough for the topic? Is it relevant to your question? Be careful with sites that have no author, no sources, a strong emotional tone or a strong sales goal. Use lateral reading: leave the page and check what other reliable sources say about the source itself. Misinformation is false information shared without intent to deceive, and disinformation is false information spread on purpose. Pause before sharing, and check headlines, dates and images, since photos can be edited or taken out of context.\n\nArtificial intelligence tools can answer questions, summarize text, help with ideas and write code. Used wisely, they are like a tutor or assistant. But AI can be wrong, can invent facts or sources, and can reflect bias. Always check important facts with reliable sources. Do not enter private information such as full names, addresses, passwords or school records into tools you do not control. Do not present AI work as your own, and follow your teacher's rules about when AI help is allowed. If AI helps you, say how, and make sure your final work shows your own understanding. Proverbs 12:22 says, Lying lips are abomination to the LORD: but they that deal truly are his delight.\n\nYour task: (1) List five questions for evaluating a source. (2) Explain the difference between misinformation and disinformation. (3) Describe three rules for using AI tools honestly.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, 1 Thessalonians 5:21 says, Prove all things; hold fast that which is good. Good researchers test what they read.\n\nNow watch this. Search with skill. Use specific keywords. Put exact phrases in quotation marks. Remember that some top results are paid advertisements.\n\nEvaluate every source. Who is the author and are they qualified? Is it accurate and supported by evidence? What is the purpose, to inform, sell or persuade? Is it current? Is it relevant? Use lateral reading, which means leaving the page to see what other reliable sources say about it.\n\nMisinformation is false information shared without intent to deceive. Disinformation is false information spread on purpose. Pause before sharing. Photos can be edited or taken out of context.\n\nAI tools can be like a tutor or assistant. But AI can be wrong, can invent facts and sources and can reflect bias. Check important facts. Do not enter private information. Do not present AI work as your own. Follow your teacher's rules. If AI helps you, say how, and make sure the final work shows your own understanding. Proverbs 12:22 says, they that deal truly are his delight.\n\nYour task is to list source questions, compare misinformation and disinformation and describe honest AI use. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Research, Evaluating Sources and Responsible Use of AI Tools$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: The Internet, Networks and Cybersecurity$j$, $j${"prompt": "Write a report of at least 250 words on the internet and online security. Use complete sentences and label each part. Nehemiah 4:9 says, Nevertheless we made our prayer unto our God, and set a watch against them day and night.\n\nPart 1: Explain the difference between the internet and the World Wide Web. Define client, server, ISP, IP address, DNS, URL and HTTPS, and explain how data travels in packets.\nPart 2: Compare a LAN and a WAN. Name the jobs of a modem, a router and a switch. List five steps to secure a home or church network.\nPart 3: Define malware, virus, ransomware, spyware and phishing. Describe five warning signs of a phishing message.\nPart 4: Describe five layers of defense for a computer or a church office, and explain what to do if a device is hacked.\nPart 5: List five questions for evaluating a source, explain misinformation and disinformation, and give three rules for honest use of AI tools. Apply 1 Thessalonians 5:21 and Proverbs 12:22.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: The Internet, Networks and Cybersecurity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Prove All Things$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when you saw or received false or suspicious information online, with no names, (2) explains in your own words how you decide whether a source can be trusted, (3) explains how a church or family can protect itself from online scams, and (4) connects your answer to 1 Thessalonians 5:21, Nehemiah 4:9, Proverbs 22:3 or Proverbs 12:22. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a believer use AI tools without being dishonest? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Prove All Things$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: How the Internet Works$j$, $j${"questions": [{"q": "The Domain Name System works like:", "options": ["A printer", "A battery", "A virus", "A phone book for web names"]}, {"q": "A device that asks for information is a:", "options": ["Client", "Router", "Packet", "Server"]}, {"q": "HTTPS differs from HTTP because it:", "options": ["Has no address", "Removes the web", "Is slower by design", "Encrypts the connection"]}, {"q": "Data travels across the internet in small pieces called:", "options": ["Pixels", "Packets", "Folders", "Passwords"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: How the Internet Works$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,1}'::int[], array[$j$DNS turns names into numbers.$j$,$j$Clients request; servers respond.$j$,$j$HTTPS scrambles data in transit.$j$,$j$Packets are reassembled at the destination.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: How the Internet Works$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Networks, WiFi and Devices$j$, $j${"questions": [{"q": "A network that covers a home or a church building is a:", "options": ["DNS", "WAN", "LAN", "URL"]}, {"q": "The device that directs traffic between your devices and the internet is a:", "options": ["Monitor", "Router", "Speaker", "Mouse"]}, {"q": "A good first step to secure a new router is to:", "options": ["Leave the default password", "Share the password publicly", "Turn off updates", "Change the default password"]}, {"q": "A VPN is used to:", "options": ["Encrypt your traffic on a network", "Increase screen size", "Print documents", "Delete viruses by itself"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Networks, WiFi and Devices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,0}'::int[], array[$j$A local area network is small in size.$j$,$j$Routers direct network traffic.$j$,$j$Default passwords are widely known.$j$,$j$A VPN protects traffic on untrusted networks.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Networks, WiFi and Devices$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Cybersecurity: Threats and Defenses$j$, $j${"questions": [{"q": "Malware that locks your files and demands payment is:", "options": ["A firewall", "Ransomware", "Adware", "A router"]}, {"q": "Fake messages that trick people into giving passwords are called:", "options": ["Streaming", "Backup", "Booting", "Phishing"]}, {"q": "A firewall:", "options": ["Cleans the screen", "Filters network traffic", "Increases RAM", "Prints pages"]}, {"q": "An important reason to install software updates is to:", "options": ["Slow the device", "Make files disappear", "Remove all passwords", "Fix known security weaknesses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Cybersecurity: Threats and Defenses$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,3}'::int[], array[$j$Ransomware holds files hostage.$j$,$j$Phishing uses deception.$j$,$j$It blocks unwanted traffic.$j$,$j$Updates patch vulnerabilities.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Cybersecurity: Threats and Defenses$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Research, Evaluating Sources and Responsible Use of AI Tools$j$, $j${"questions": [{"q": "False information spread on purpose is called:", "options": ["A cookie", "Backup", "A router", "Disinformation"]}, {"q": "Putting words in quotation marks in a search finds:", "options": ["That exact phrase", "Random pages", "Nothing", "Only images"]}, {"q": "AI tools can sometimes:", "options": ["Give wrong answers and invent sources", "Know your password", "Never be wrong", "Replace all checking"]}, {"q": "Lateral reading means:", "options": ["Skipping the author", "Reading faster", "Checking what other sources say about a source", "Reading sideways"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Research, Evaluating Sources and Responsible Use of AI Tools$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,2}'::int[], array[$j$Disinformation is deliberate.$j$,$j$Quotation marks search for exact phrases.$j$,$j$AI output must be verified.$j$,$j$It tests the credibility of a source.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Research, Evaluating Sources and Responsible Use of AI Tools$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: The Internet, Networks and Cybersecurity$j$, $j${"questions": [{"q": "The internet differs from the web because the internet is:", "options": ["Only a browser", "A search engine", "Only email", "The infrastructure the web runs on"]}, {"q": "A number that identifies a device on a network is an:", "options": ["Font", "Folder", "Email subject", "IP address"]}, {"q": "A secure website address begins with:", "options": ["HTTP only", "HTTPS", "None of these", "FTP only"]}, {"q": "A router:", "options": ["Directs traffic between devices and the internet", "Blocks all sound", "Stores your photos only", "Prints pages"]}, {"q": "Which is a sign of phishing?", "options": ["A song", "A calendar reminder you set", "A letter you expected from your teacher", "An urgent request for your password from an unknown sender"]}, {"q": "Backups help defeat ransomware because:", "options": ["They speed up WiFi", "They remove all viruses", "They stop updates", "You can restore files without paying"]}, {"q": "1 Thessalonians 5:21 tells us to:", "options": ["Avoid all learning", "Believe everything", "Share rumors", "Prove all things; hold fast that which is good"]}, {"q": "When using an AI tool for school, you should:", "options": ["Check facts and follow your teacher's rules", "Trust it without checking", "Submit its work as your own", "Enter your passwords"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: The Internet, Networks and Cybersecurity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,0,3,3,3,0}'::int[], array[$j$The web is one service on the internet.$j$,$j$IP addresses route data.$j$,$j$HTTPS encrypts traffic.$j$,$j$Routers direct network traffic.$j$,$j$Urgent requests for passwords are warning signs.$j$,$j$A clean backup restores your data.$j$,$j$Test information before trusting it.$j$,$j$Verify and be honest.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: The Internet, Networks and Cybersecurity$j$ on conflict (item_id) do nothing;
